/**
 * emit to subscription queries of type FindTradeOrder,
 * but only if the id matches
 *
 * @param		entity	TradeOrder
 */
	protected void emitFindTradeOrder( TradeOrder entity ) {
		LOGGER.info("handling emitFindTradeOrder" );
		
	    queryUpdateEmitter.emit(FindTradeOrderQuery.class,
	                            query -> query.getFilter().getTradeOrderId().equals(entity.getTradeOrderId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTradeOrder
	 * 
	 * @param		entity	TradeOrder
	 */
	protected void emitFindAllTradeOrder( TradeOrder entity ) {
		LOGGER.info("handling emitFindAllTradeOrder" );
		
	    queryUpdateEmitter.emit(FindAllTradeOrderQuery.class,
	                            query -> true,
	                            entity);
	}

